CREATE TABLE "CV_DISK_OBSERVATIONS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SOURCE_KEY" CHAR(64) NOT NULL,
    "FILE_NAME" TEXT NOT NULL,
    "SIZE_BYTES" BIGINT NOT NULL CHECK ("SIZE_BYTES" >= 0),
    "MODIFIED" VARCHAR(40) NOT NULL,
    "FILE_KEY" TEXT NOT NULL,
    "OBSERVED_SINCE" TIMESTAMPTZ NOT NULL,
    "LAST_SCAN" UUID NOT NULL,
    "READ_ATTEMPTS" INTEGER NOT NULL DEFAULT 0 CHECK ("READ_ATTEMPTS" >= 0),
    "NEXT_READ_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ERROR_CODE" VARCHAR(40),
    UNIQUE ("SOURCE_KEY", "FILE_NAME")
);
CREATE INDEX "IX_DISK_OBSERVATION_SCAN" ON "CV_DISK_OBSERVATIONS" ("SOURCE_KEY", "LAST_SCAN", "FILE_NAME" COLLATE "C");
CREATE TABLE "CV_DISK_IMPORT_FILES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SOURCE_KEY" CHAR(64) NOT NULL,
    "FILE_NAME" TEXT NOT NULL,
    "SHA256" CHAR(64) NOT NULL CHECK ("SHA256"::TEXT ~ '^[0-9a-f]{64}$'),
    "SIZE_BYTES" BIGINT NOT NULL CHECK ("SIZE_BYTES" >= 0),
    "MODIFIED" VARCHAR(40) NOT NULL,
    "FILE_KEY" TEXT NOT NULL,
    "STATE" VARCHAR(30) NOT NULL CHECK ("STATE" IN ('PENDING','QUEUED','IMPORTING','RETRY_WAIT','SUCCEEDED_MOVE','FAILED_MOVE','PROCESSED','FAILED','NEEDS_ATTENTION')),
    "ATTEMPTS" INTEGER NOT NULL DEFAULT 0 CHECK ("ATTEMPTS" >= 0),
    "READ_FAILURES_APPLIED" INTEGER NOT NULL DEFAULT 0 CHECK ("READ_FAILURES_APPLIED" >= 0),
    "MOVE_ATTEMPTS" INTEGER NOT NULL DEFAULT 0 CHECK ("MOVE_ATTEMPTS" >= 0),
    "NEXT_ATTEMPT_AT" TIMESTAMPTZ NOT NULL,
    "NEXT_MOVE_AT" TIMESTAMPTZ NOT NULL,
    "BATCH_ID" BIGINT REFERENCES "CV_IMPORT_BATCHES"("ID"),
    "DOCUMENT_ID" BIGINT REFERENCES "CV_DOCUMENTS"("ID"),
    "ERROR_CODE" VARCHAR(40),
    "MOVE_ERROR_CODE" VARCHAR(40),
    "TARGET_NAME" VARCHAR(36) NOT NULL,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPDATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE ("SOURCE_KEY", "FILE_NAME", "SHA256"),
    CHECK (("STATE" NOT IN ('SUCCEEDED_MOVE','PROCESSED')) OR "DOCUMENT_ID" IS NOT NULL)
);
CREATE INDEX "IX_DISK_IMPORT_MOVE" ON "CV_DISK_IMPORT_FILES" ("SOURCE_KEY", "STATE", "NEXT_MOVE_AT", "ID");
